ee:message.ee:set-payload:
%dw 2.0
output text/xml
ns soapenv http://schemas.xmlsoap.org/soap/envelope/
ns tem http://tempuri.org/
ns orq http://www.etb.com.co/orquestador
---
{
  soapenv#"Envelope": {
    soapenv#"Header": null,
    soapenv#"Body": {
      tem#"ObtenerOrdenOFSC": {
        tem#"solicitud": {
          orq#"Encabezado": {
            orq#"Sistema": {
              orq#"IdCorrelacion": correlationId,
              orq#"Nombre": "MuleSoft"
            }
          },
          orq#"DatosSolicitud": {
            orq#"Orden": vars.orderNumber
          }
        }
      }
    }
  }
}

%dw 2.0
output application/json
var response = payload.Envelope.Body.ObtenerOrdenOFSCResponse.Resultado
---
if(response.Ordenes != null or !isEmpty(response.Ordenes))
{
    "Encabezado" : response.Encabezado,
    "Cantidad": response.Cantidad,
    "Ordenes": (response.Ordenes pluck $) map ((item, index) -> {
	    ActivityId: item.ActivityId,
	    Numero_Orden: item.Numero_Orden,
	    Estado: item.Estado,
	    Posicion: item.Posicion,
	    InformacionAdicional: item.Informacion pluck $
    })
} else response
